def transform(grid):
    """Restore the latent motif using its half-turn symmetry.

    The overwritten 2 regions appear in half-turn-corresponding pairs. Their
    underlying colors are obtained by rotating the visible surrounding pattern
    180 degrees; use a snapshot so filling one masked cell never affects another.
    """
    n, m = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(m):
            if src[r][c] == 2:
                # If the counterpart is also overwritten, the visible motif's
                # reflection across the main diagonal supplies the matching cell.
                rr, cc = n - 1 - r, m - 1 - c
                if src[rr][cc] != 2:
                    out[r][c] = src[rr][cc]
                elif c < n and r < m and src[c][r] != 2:
                    out[r][c] = src[c][r]
    return out
